  function renderControlWorkspace() {
    const events=eventItems().filter(e=>e.date).slice(0,25), issues=complianceIssues(); const docs=state.documents.slice().sort((a,b)=>String(a.expiryDate||'9999').localeCompare(String(b.expiryDate||'9999')));
    return `${head('Control Centre','The place to control deadlines, contract renewals, documents, compliance and management tasks. These are generated from the connected records; they are not separate copies.',`<button class="secondary" data-action="calendar-export">Export calendar</button><button class="secondary" data-action="form" data-type="document">Add document</button><button class="primary" data-action="form" data-type="task">Add task</button>`)}
      <div class="grid two"><section class="panel"><div class="panel-head"><h3>Deadline timeline</h3><span>${events.length} linked item(s)</span></div><div class="panel-body"><ul class="action-list">${events.map(e=>`<li><div><b>${esc(e.label)}</b><span>${dateLabel(e.date)} · ${esc(e.kind)}</span></div>${badge(diffDays(e.date)<0?'Overdue':`${diffDays(e.date)} days`,diffDays(e.date)<0?'red':e.level==='gold'?'gold':'blue')}</li>`).join('')||'<li><span>No deadlines recorded.</span></li>'}</ul></div></section><section class="panel"><div class="panel-head"><h3>Control exceptions</h3><span>${issues.length} item(s)</span></div><div class="panel-body"><ul class="action-list">${issues.map(i=>`<li><div><b>${esc(i.kind)} · ${esc(i.name)}</b><span>${esc(i.detail)}</span></div>${badge(i.level==='red'?'Action required':'Review',i.level)}</li>`).join('')||'<li><span>All monitored controls are clear.</span></li>'}</ul></div></section></div>
      <section class="panel" style="margin-top:18px"><div class="panel-head"><h3>Document register</h3><span>Linked evidence and agreements</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Document</th><th>Linked property / agreement</th><th>Status</th><th>Review date</th><th>Uploaded / registered</th><th>Vault</th><th></th></tr></thead><tbody>${docs.map(d=>`<tr><td><span class="main">${esc(d.name)}</span><span class="sub">${esc(d.type)}</span></td><td>${esc(propertyName(d.propertyId||lease(d.leaseId)?.propertyId))}<span class="sub">${esc(leaseName(d.leaseId))}</span></td><td>${badge(d.status||'Current',d.status==='Current'?'green':'grey')}</td><td>${dateLabel(d.expiryDate)}</td><td>${dateTimeLabel(d.uploadedAt||d.createdAt)}</td><td>${d.storagePath?'Private vault':'Register only'}</td><td>${d.storagePath?`<button class="link-button" data-action="document-open" data-id="${d.id}">Open</button> · `:''}<button class="link-button" data-action="form" data-type="document" data-id="${d.id}">Edit</button></td></tr>`).join('')||noRows(7,'Register signed contracts, notices, statements, quotes and inspection evidence.')}</tbody></table></div></section>`;
  }

  function renderReportsWorkspace() {
    const selected=state.properties.some(p=>p.id===state.ui.reportProperty)?state.ui.reportProperty:''; const scoped=id=>!selected||id===selected; const scopedUnits=state.units.filter(u=>scoped(u.propertyId)); const scopedLeases=state.leases.filter(l=>scoped(l.propertyId)); const scopedPayments=state.payments.filter(p=>scoped(p.propertyId||lease(p.leaseId)?.propertyId)); const scopedWorks=state.workOrders.filter(w=>scoped(w.propertyId)); const scopedMunicipal=state.municipalAccounts.filter(m=>scoped(m.propertyId));
    return `${head('Insights & reports','Flexible, live reporting from the same connected records. Choose one property for a management pack or keep “Entire portfolio”.',`<button class="secondary" data-action="export-report">Export selected report CSV</button><button class="primary" data-action="backup">Download full backup</button>`)}
      <section class="scope-bar"><div><label>Report scope</label><select id="reportPropertyScope"><option value="">Entire portfolio</option>${state.properties.map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${esc(propertyName(p.id))}</option>`).join('')}</select></div><div class="scope-address"><b>${selected?esc(propertyName(selected)):'Entire portfolio'}</b><span>Scope changes the live summary below without duplicating data.</span></div></section>
      <div class="kpis"><div class="kpi"><label>Units</label><strong>${scopedUnits.length}</strong><small>${scopedUnits.filter(u=>u.status==='Occupied').length} occupied</small></div><div class="kpi"><label>Contracted income</label><strong>${money(scopedLeases.filter(l=>activeStatus(l.status)).reduce((s,l)=>s+Number(l.monthlyRent||0),0))}</strong><small>Active agreements</small></div><div class="kpi"><label>Receipts this month</label><strong>${money(scopedPayments.filter(p=>String(p.paymentDate).slice(0,7)===today().slice(0,7)).reduce((s,p)=>s+Number(p.amount||0),0))}</strong><small>Selected scope</small></div><div class="kpi"><label>Service cost actual</label><strong>${money(scopedWorks.reduce((s,w)=>s+Number(w.actualCost||0),0))}</strong><small>Recorded work orders</small></div></div>
      <div class="grid equal"><section class="panel"><div class="panel-head"><h3>Management report builder</h3></div><div class="panel-body"><div class="report-actions"><button class="secondary" data-report="executive">Executive overview</button><button class="secondary" data-report="finance">Receivables</button><button class="secondary" data-report="leases">Contract & renewal</button><button class="secondary" data-report="vacancy">Vacancy</button><button class="secondary" data-report="operations">Service</button><button class="secondary" data-report="municipal">Municipal</button><button class="secondary" data-report="documents">Document control</button><button class="secondary" data-report="compliance">Exceptions</button></div><p class="sub">Choose a report, filter it with Smart Filter, then export its CSV for management.</p></div></section><section class="panel"><div class="panel-head"><h3>Scope controls</h3></div><div class="panel-body"><div class="list-kpi"><span>Municipal balance</span><strong>${money(scopedMunicipal.reduce((s,m)=>s+Number(m.balance||0),0))}</strong></div><div class="list-kpi"><span>Open service work</span><strong>${scopedWorks.filter(w=>w.status!=='Completed').length}</strong></div><div class="list-kpi"><span>Expiring agreements</span><strong>${scopedLeases.filter(l=>l.endDate&&diffDays(l.endDate)<=90&&activeStatus(l.status)).length}</strong></div><div class="list-kpi"><span>Open compliance items</span><strong>${complianceIssues().filter(i=>!selected||i.name.includes(propertyName(selected))).length}</strong></div></div></section></div>
      <div style="margin-top:18px">${renderReportDetail(state.ui.report||'executive')}</div>`;
  }

  /* Smart finding is deliberately shared by every module: a manager should not need
     to remember which screen owns a tenant, a contract, a payment or a work order. */
  const smartHints = {
    dashboard:'Search actions and activity', calendar:'Search dates, tasks and events', portfolio:'Search property, ERF, address or unit', people:'Search owner, prospect, phone or vacancy', leases:'Search tenant, lease number or unit', renewals:'Search lease, stage or approval', finance:'Search receipt, tenant, charge or payment method', municipal:'Search property, account number or due status', operations:'Search work order, supplier, unit or inspection', documents:'Search file, contract or compliance item', reports:'Search report data', admin:'Search team and audit activity'
  };
  function injectSmartFilters(view) {
    const tables=$$('#app .table-wrap');
    if(!tables.length) return;
    const panelTables=new Map();
    tables.forEach((wrap,index)=>{
      const panel=wrap.closest('.panel');
      if(!panel || panelTables.has(panel)) return;
      panelTables.set(panel,index);
      const label=panel.querySelector('.panel-head h3')?.textContent || 'Records';
      const toolbar=document.createElement('div');
      toolbar.className='smart-filter-bar';
      toolbar.innerHTML=`<div class="filter-title"><b>Smart filter</b><span>${esc(label)}</span></div><input type="search" class="table-search" placeholder="${esc(smartHints[view]||'Filter these records')}" aria-label="Filter ${esc(label)}"><select class="table-intent" aria-label="Quick filter"><option value="">All records</option><option value="attention">Needs attention</option><option value="active">Active / open</option><option value="closed">Completed / closed</option></select><button type="button" class="filter-reset">Reset</button><span class="filter-count"></span>`;
      wrap.before(toolbar);
      const apply=()=>applyTableFilter(wrap,toolbar);
      toolbar.querySelector('.table-search').addEventListener('input',apply);
      toolbar.querySelector('.table-intent').addEventListener('change',apply);
      toolbar.querySelector('.filter-reset').addEventListener('click',()=>{toolbar.querySelector('.table-search').value='';toolbar.querySelector('.table-intent').value='';apply();});
      apply();
    });
  }
  function applyTableFilter(wrap, toolbar) {
    const query=toolbar.querySelector('.table-search').value.trim().toLowerCase();
    const intent=toolbar.querySelector('.table-intent').value;
    const rows=[...wrap.querySelectorAll('tbody tr')]; let visible=0;
    rows.forEach(row=>{
      if(row.querySelector('.empty')) return;
      const text=row.textContent.toLowerCase();
      const matchesText=!query || text.includes(query);
      const attention=/(overdue|expired|action required|review|urgent|vacant|open billed|defect|draft|not started|not requested|unavailable)/.test(text);
      const active=/(active|occupied|available|open|scheduled|current|approved|in progress)/.test(text) && !/(completed|closed|declined|archived)/.test(text);
      const closed=/(completed|closed|declined|archived|paid|let)/.test(text);
      const matchesIntent=!intent || (intent==='attention'&&attention) || (intent==='active'&&active) || (intent==='closed'&&closed);
      row.hidden=!(matchesText&&matchesIntent);
      if(!row.hidden) visible++;
    });
    toolbar.querySelector('.filter-count').textContent=`${visible} shown`;
  }
  function globalSearchItems() {
    const entries=[];
    const add=(view,title,detail,keywords,kind)=>entries.push({view,title,detail,keywords:`${title} ${detail} ${keywords||''}`.toLowerCase(),kind});
    state.properties.forEach(p=>add('portfolio',`${p.code} · ${p.name}`,p.address||p.type,`${p.erf||''} ${p.status}`,'Property'));
    state.units.forEach(u=>add('portfolio',`${propertyName(u.propertyId)} · ${u.name}`,`${u.status} · ${money(u.marketRent)}`,u.type,'Unit'));
    state.contacts.forEach(c=>add('people',c.name,`${c.kind||'Contact'} · ${c.phone||c.email||''}`,`${c.phone||''} ${c.email||''}`,'Person'));
    state.owners.forEach(o=>add('people',o.name,`Owner · ${propertyName(o.propertyId)}`,`${o.phone||''} ${o.email||''}`,'Owner'));
    state.prospects.forEach(p=>add('people',p.name,`Prospect · ${p.stage||'Lead'} · ${propertyName(p.propertyId)}`,`${p.phone||''} ${p.email||''}`,'Prospect'));
    state.leases.forEach(l=>add('leases',leaseName(l.id),`${l.status} · expiry ${dateLabel(l.endDate)}`,`${l.leaseNo} ${l.agreementRef||''}`,'Contract'));
    state.renewals.forEach(r=>add('renewals',leaseName(r.leaseId),`${r.stage} · ${r.legalStatus} · ${r.approvalStatus}`,r.agreementRef||'','Renewal'));
    state.payments.forEach(p=>add('finance',p.receiptNo,`${leaseName(p.leaseId)} · ${money(p.amount)} · ${dateLabel(p.paymentDate)}`,`${p.method||''} ${p.period||''}`,'Payment'));
    state.invoices.forEach(c=>add('finance',leaseName(c.leaseId),`${c.type||'Charge'} · open ${money(chargeBalance(c))} · due ${dateLabel(c.dueDate)}`,c.description||'','Charge'));
    state.municipalAccounts.forEach(m=>add('municipal',propertyName(m.propertyId),`Account ${m.accountNo||'—'} · ${money(m.balance)} · due ${dateLabel(m.dueDate)}`,m.notes||'','Municipal'));
    state.workOrders.forEach(w=>add('operations',w.title,`${propertyName(w.propertyId)} · ${w.status} · ${w.priority}`,`${w.category||''} ${w.assignee||''} ${vendor(w.vendorId)?.name||''}`,'Work order'));
    state.inspections.forEach(i=>add('operations',`${i.type} inspection`,`${propertyName(i.propertyId)} · ${i.status} · ${dateLabel(i.date)}`,`${i.inspector||''} ${i.defects||''}`,'Inspection'));
    state.documents.forEach(d=>add('documents',d.name,`${d.type||'Document'} · ${d.status||'Current'} · ${dateLabel(d.expiryDate)}`,`${leaseName(d.leaseId)} ${propertyName(d.propertyId)}`,'Document'));
    complianceIssues().forEach(i=>add('documents',i.name,`${i.kind}: ${i.detail}`,'overdue action attention','Attention'));
    return entries;
  }
  function searchWorkspace(query) {
    const output=$('#searchResults'); const q=query.trim().toLowerCase();
    if(!q){output.hidden=true;output.innerHTML='';return;}
    let items=globalSearchItems();
    const intentWords={overdue:['overdue','expired','action required'],attention:['overdue','expired','action required','defect'],renewal:['renewal','expiry','contract'],contract:['lease','contract','agreement'],arrears:['charge','open'],vacant:['vacant','listing'],municipal:['municipal','account'],maintenance:['work order','inspection']};
    const intent=intentWords[q];
    if(intent) items=items.filter(item=>intent.some(word=>item.keywords.includes(word)));
    else {const terms=q.split(/\s+/).filter(Boolean);items=items.filter(item=>terms.every(term=>item.keywords.includes(term)));}
    const matches=items.slice(0,9);
    output.innerHTML=matches.length?`<div class="search-caption">${matches.length}${items.length>matches.length?'+':''} matching records</div>${matches.map(item=>`<button type="button" class="search-result" data-search-view="${item.view}"><span class="result-kind">${esc(item.kind)}</span><span><b>${esc(item.title)}</b><small>${esc(item.detail)}</small></span><i>Open →</i></button>`).join('')}`:`<div class="search-empty">No exact record found. Try a property, tenant, lease number, receipt, “overdue”, “renewal”, “vacant”, “municipal” or “maintenance”.</div>`;
    output.hidden=false;
  }

